package com.demo.order.domain;

import java.util.UUID;
import java.util.regex.Pattern;

/** Identifier of an {@link Order}, always generated by the service: a UUID in canonical form. */
public record OrderId(String value) {

    private static final Pattern CANONICAL_UUID =
            Pattern.compile("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");

    public OrderId {
        if (value == null || value.isBlank()) {
            throw new InvalidIdentifierException("Order id");
        }
        if (!CANONICAL_UUID.matcher(value).matches()) {
            throw new InvalidOrderIdException();
        }
    }

    /** Whether {@code value} would make a valid order id, for callers that must not throw on untrusted input. */
    public static boolean isWellFormed(String value) {
        return value != null && CANONICAL_UUID.matcher(value).matches();
    }

    public static OrderId newId() {
        return new OrderId(UUID.randomUUID().toString());
    }
}
